#!/bin/bash
set -e
B64=""
echo "$B64" | base64 -d > /tmp/wecom10081.tar.gz
mkdir -p /opt/holang
tar -xzf /tmp/wecom10081.tar.gz -C /opt/holang
cd /opt/holang/wecom-app-1000081
echo "=== npm install ==="
npm install 2>&1 | tail -6
echo "=== deployed files ==="
ls -la /opt/holang/wecom-app-1000081
echo "=== node check ==="
node -e "console.log('node', process.version)"
echo "=== DONE deploy_files ==="
